import { writeFileSync } from "node:fs";
import { join } from "node:path";
import type { Post } from "./types.js";

export function generateRss(
  posts: Post[],
  outputDir: string,
  baseUrl: string,
  siteTitle: string,
  siteDescription: string
): void {
  const now = new Date().toUTCString();

  const items = posts
    .filter((p) => p.date)
    .map(
      (p) => `    <item>
      <title><![CDATA[${p.title}]]></title>
      <link>${baseUrl}${p.slug}/</link>
      <guid>${baseUrl}${p.slug}/</guid>
      <pubDate>${p.date!.toUTCString()}</pubDate>
      <description><![CDATA[${p.content.slice(0, 300)}]]></description>
    </item>`
    )
    .join("\n");

  const rss = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${siteTitle}</title>
    <link>${baseUrl}</link>
    <description>${siteDescription}</description>
    <language>en</language>
    <lastBuildDate>${now}</lastBuildDate>
    <atom:link href="${baseUrl}rss.xml" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>`;

  writeFileSync(join(outputDir, "rss.xml"), rss);
}

import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { readFileSync, existsSync, statSync } from "node:fs";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import type { BuilderOptions } from "./types.js";
import { build } from "./build.js";

const MIME: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
  ".json": "application/json",
};

const RELOAD_SCRIPT = `
<script>(function(){
  var ws=new WebSocket('ws://'+location.host);
  ws.onmessage=function(e){if(e.data==='reload')location.reload();};
})();</script>`;

let wss: WebSocketServer;

function serveFile(res: ServerResponse, filePath: string): void {
  if (!existsSync(filePath)) {
    res.writeHead(404);
    res.end("Not found");
    return;
  }
  const ext = extname(filePath);
  const mime = MIME[ext] || "application/octet-stream";
  let data = readFileSync(filePath);

  if (ext === ".html") {
    data = Buffer.from(data.toString() + RELOAD_SCRIPT);
  }

  res.writeHead(200, {
    "Content-Type": mime,
    "Content-Length": data.length,
    "Cache-Control": "no-cache",
  });
  res.end(data);
}

export function startServer(opts: BuilderOptions, port: number = 3000): void {
  build(opts);

  const watcher = chokidar.watch([opts.sourceDir, opts.templateDir], {
    ignoreInitial: true,
  });

  const rebuild = () => {
    try {
      build(opts);
      if (wss) {
        for (const client of wss.clients) {
          if (client.readyState === WebSocket.OPEN) client.send("reload");
        }
      }
    } catch (e) {
      console.error("Build error:", e);
    }
  };

  watcher.on("all", rebuild);

  const server = createServer((req: IncomingMessage, res: ServerResponse) => {
    const url = req.url === "/" ? "/index.html" : req.url ?? "/index.html";
    const filePath = join(opts.outputDir, url);
    if (existsSync(filePath) && statSync(filePath).isFile()) {
      serveFile(res, filePath);
    } else if (existsSync(filePath) && statSync(filePath).isDirectory()) {
      serveFile(res, join(filePath, "index.html"));
    } else {
      serveFile(res, join(opts.outputDir, "index.html"));
    }
  });

  wss = new WebSocketServer({ server });
  wss.on("connection", (ws) => {
    ws.send("connected");
  });

  server.listen(port, () => {
    console.log(`Dev server at http://localhost:${port}`);
  });
}

#!/usr/bin/env node
import { Command } from "commander";
import { build } from "./build.js";
import { startServer } from "./server.js";
import { generateRss } from "./rss.js";
import type { BuilderOptions } from "./types.js";

function makeOpts(cmd: Command): BuilderOptions {
  const opts = cmd.opts();
  return {
    sourceDir: opts.source,
    templateDir: opts.templates,
    outputDir: opts.output,
    baseUrl: opts.baseUrl ?? "http://localhost:3000/",
    siteTitle: opts.title ?? "My Site",
    siteDescription: opts.description ?? "A static site",
  };
}

const program = new Command()
  .name("static-gen")
  .version("1.0.0")
  .description("Static site generator");

program.option("-s, --source <dir>", "Source directory of markdown files", "content")
  .option("-t, --templates <dir>", "Template directory of Handlebars files", "templates")
  .option("-o, --output <dir>", "Output directory for generated HTML", "dist")
  .option("--base-url <url>", "Site base URL", "http://localhost:3000/")
  .option("--title <title>", "Site title", "My Site")
  .option("--description <desc>", "Site description", "A static site");

program
  .command("build")
  .description("Build the static site")
  .action(() => {
    const opts = makeOpts(program);
    const result = build(opts);
    generateRss(result.posts, opts.outputDir, opts.baseUrl, opts.siteTitle, opts.siteDescription);
    console.log(`Built ${result.posts.length} posts, ${result.tagPages.length} tag pages to ${opts.outputDir}`);
  });

program
  .command("serve")
  .description("Start dev server with live reload")
  .option("-p, --port <port>", "Port to listen on", "3000")
  .action((cmd) => {
    const opts = makeOpts(program);
    startServer(opts, parseInt(cmd.port, 10));
  });

program.parse();

